/* Returns one icon as an <svg> string. `extraClass` is appended to the
 * default "icon" class so callers can size or colour a single use without a
 * new rule for every site. An unknown name is a programming error and says
 * so in the console rather than silently rendering nothing. */
function faIcon(name, extraClass) {
  const icon = FA_ICONS[name];
  if (!icon) {
    console.error('faIcon: no such icon "' + name + '"');
    return '';
  }
  const cls = extraClass ? 'icon ' + extraClass : 'icon';
  return '<svg class="' + cls + '" viewBox="' + icon.vb +
         '" xmlns="http://www.w3.org/2000/svg" aria-hidden="true" focusable="false">' +
         '<path d="' + icon.d + '"/></svg>';
}

/* Fills in icons for static markup: any element carrying data-icon="<name>"
 * gets that icon prepended to its content. Call it from a synchronous
 * <script> right after the markup so the icon is there before the first
 * paint, or after rendering a fragment. Safe to call repeatedly -- an
 * element is only hydrated once. */
function hydrateIcons(root) {
  (root || document).querySelectorAll('[data-icon]').forEach((el) => {
    if (el.dataset.iconDone) return;
    el.insertAdjacentHTML('afterbegin', faIcon(el.dataset.icon));
    el.dataset.iconDone = '1';
  });
}

/* Shared CTA destinations. Every outbound link in the lab carries these
 * UTMs: the lab is a local app that runs offline and reports nothing, so an
 * outbound query string is the only way to tell that a course sale started
 * here rather than on GitHub. utm_content names the surface, so the nav CTA
 * and, say, a chapter link can be told apart in analytics. */
const TAOP_SITE = 'https://theartofpostgresql.com';

function taopURL(path, content) {
  return TAOP_SITE + path +
         '?utm_source=lab&utm_medium=app&utm_content=' + encodeURIComponent(content);
}
